let input = null;
try { input = $('Input').item.json; } catch (e) { input = null; }
return [{ json: {
  requested_by: (input && input.requested_by) || 'manual',
  slug: (input && input.slug) || '',
  channel_id: (input && input.channel_id) || 'C0BQH5S6P1P',
  bot_id: (input && input.bot_id) || ''
} }];

const cfg = $('Config').first().json;
const rid = $('Run Id').first().json.run_id;
const env = String($vars.env || 'staging');
const out = [];
for (const item of $input.all()) {
  const c = item.json;
  if (cfg.slug && c.slug !== cfg.slug) continue;
  if (c.env !== 'any' && c.env !== env) continue;
  out.push({ json: Object.assign({}, c, { run_id: rid }) });
}
return out;

const cfg = $('Config').first().json;
const out = [];
for (const item of $input.all()) {
  const c = item.json;
  const k = Number(c.k) || 5;
  for (let a = 1; a <= k; a++) {
    out.push({ json: { run_id: c.run_id, case_id: c.id, attempt: String(a), channel_id: cfg.channel_id, bot_id: cfg.bot_id } });
  }
}
return out;

const rid = $('Run Id').first().json.run_id;
const cases = $('Filter Cases').all().map(i => i.json);
const expected = cases.reduce((n, c) => n + (Number(c.k) || 5), 0);
const rows = $input.all().map(i => i.json).filter(r => r.run_id === rid);
const seen = new Set();
let landed = 0;
for (const r of rows) {
  const key = r.case_id + '-' + r.attempt;
  if (seen.has(key)) continue;
  seen.add(key);
  landed++;
}
const poll = ($runIndex || 0) + 1;
return [{ json: { run_id: rid, expected: expected, landed: landed, polls: poll, complete: landed >= expected, timeout: poll >= 45 } }];

const rid = $('Run Id').first().json.run_id;
const cases = $('Filter Cases').all().map(i => i.json);
const rows = $('Load Attempts').all().map(i => i.json).filter(r => r.run_id === rid);
const byCase = {};
for (const r of rows) {
  if (!byCase[r.case_id]) byCase[r.case_id] = new Map();
  if (!byCase[r.case_id].has(r.attempt)) byCase[r.case_id].set(r.attempt, r);
}
return cases.map(c => {
  const attempts = Array.from((byCase[c.id] || new Map()).values()).sort((a, b) => a.attempt - b.attempt);
  const ok = attempts.filter(a => a.status === 'ok');
  return { json: Object.assign({}, c, {
    attempts: attempts.map(a => ({ attempt: a.attempt, status: a.status, execution_url: a.execution_url })),
    ok_attempts: ok.map(a => ({ attempt: a.attempt, answer: a.agent_output })),
    ok_count: ok.length
  }) };
});

const rid = $('Run Id').first().json.run_id;
const cfg = $('Config').first().json;
const rows = $input.all().map(i => i.json).filter(r => r.run_id === rid);
const attemptRows = $('Load Attempts').all().map(i => i.json).filter(r => r.run_id === rid);
const caseItems = $('Cases For Judging').all().map(i => i.json);
const byCase = {};
for (const a of attemptRows) {
  if (!byCase[a.case_id]) byCase[a.case_id] = new Map();
  if (!byCase[a.case_id].has(a.attempt)) byCase[a.case_id].set(a.attempt, a);
}
const ICON = { pass: '✅', fail: '❌', error: '💥' };
const lines = [];
const passed = rows.filter(r => r.status === 'pass').length;
lines.push('## Consistency evals (pass^k) — `' + rid + '`', '');
lines.push('**' + passed + '/' + rows.length + ' pass** · answers are live threads in <#' + cfg.channel_id + '>', '');
lines.push('| Case | Status | Cluster | Accurate | Valid |');
lines.push('| --- | --- | --- | --- | --- |');
for (const r of rows) {
  lines.push('| `' + r.case_slug + '` | ' + (ICON[r.status] || '') + ' ' + r.status + ' | ' + (r.cluster_size === null || r.cluster_size === undefined ? '\u2014' : r.cluster_size) + '/' + r.k + ' (min ' + r.min_consistent + ') | ' + (r.accurate_attempts === null || r.accurate_attempts === undefined ? '\u2014' : r.accurate_attempts + '/' + r.k) + ' | ' + r.valid_attempts + '/' + r.k + ' |');
}
for (const r of rows) {
  let judge = r.judge;
  if (typeof judge === 'string') { try { judge = JSON.parse(judge); } catch (e) { judge = null; } }
  const claimsByAttempt = {};
  if (judge && Array.isArray(judge.claims)) {
    for (const c of judge.claims) claimsByAttempt[Number(c.attempt)] = c.core_claims || [];
  }
  const accByAttempt = {};
  if (judge && Array.isArray(judge.accuracy)) {
    for (const a of judge.accuracy) accByAttempt[Number(a.attempt)] = a;
  }
  const cluster = new Set(((judge && judge.cluster) || []).map(Number));
  const medoid = judge ? Number(judge.medoid) : null;
  lines.push('', '---', '', '### `' + r.case_slug + '` — ' + (ICON[r.status] || '') + ' ' + r.status);
  const caseItem = caseItems.find(c => c.id === r.case_id);
  if (caseItem) lines.push('', '> ' + String(caseItem.prompt).replace(/\n+/g, ' '));
  if (judge && judge.skipped) lines.push('', '_Judge skipped: ' + judge.reason + '_');
  const attempts = Array.from((byCase[r.case_id] || new Map()).values()).sort((a, b) => a.attempt - b.attempt);
  for (const a of attempts) {
    const n = Number(a.attempt);
    let membership;
    if (a.status !== 'ok') membership = a.status === 'error' ? '💥 error' : '⚠️ anchor_fail';
    else if (cluster.has(n)) membership = 'in cluster ✅' + (medoid === n ? ' · medoid' : '');
    else if (judge && !judge.skipped) membership = 'OUTLIER ⚠️';
    else membership = 'ok';
    const acc = accByAttempt[n];
    let accLabel = '';
    if (acc) {
      if (acc.contradicted === true) accLabel = ' · CONTRADICTS ground truth ⛔';
      else if (Array.isArray(acc.missing) && acc.missing.length) accLabel = ' · incomplete: misses \"' + acc.missing.join('\", \"') + '\"';
      else accLabel = ' · accurate ✅';
    }
    lines.push('', '**Attempt ' + a.attempt + '** — ' + membership + accLabel + (a.execution_url ? ' · <' + a.execution_url + '|exec>' : ''));
    const claims = claimsByAttempt[n];
    if (claims && claims.length) lines.push('_' + claims.join(' · ') + '_');
  }
  if (judge && Array.isArray(judge.pairs)) {
    const dis = judge.pairs.filter(p => p.agree === false);
    if (dis.length) {
      lines.push('', '**Disagreements:**');
      for (const p of dis) lines.push('- attempts ' + p.a + ' vs ' + p.b + ': ' + p.reason);
    }
  }
}
const base = String($vars.instance_url || 'https://darwin-staging.app.n8n.cloud').replace(/\/$/, '');
lines.push('', '_Generated ' + new Date().toISOString() + '_ · <' + base + '/workflow/' + $workflow.id + '/executions/' + $execution.id + '|Dispatcher execution>');
return [{ json: { markdown: lines.join('\n') } }];

const PER_BLOCK = 2900;
const MAX_BLOCKS = 50;
const MAX_PAYLOAD_BYTES = 90000;
const TRUNCATION_NOTE = '\n\n_… (truncated: response too long for a single Slack message)_';

let text = $json.markdown ?? '';
const fullText = text;

function estimatePayloadSize(blocksArr) {
  return JSON.stringify(blocksArr).length + 20;
}

function splitIntoChunks(str, chunkSize, maxBlocks, maxBytes) {
  const chunks = [];
  const trialBlocks = [];

  while (str.length > 0 && chunks.length < maxBlocks) {
    if (str.length <= chunkSize) {
      chunks.push(str);
      trialBlocks.push({ type: 'markdown', text: str });
      if (estimatePayloadSize(trialBlocks) > maxBytes) {
        const removed = chunks.pop();
        trialBlocks.pop();
        const remaining = maxBytes - estimatePayloadSize(trialBlocks);
        const maxTextLen = Math.max(0, remaining - 60);
        if (maxTextLen > 50) {
          chunks.push(removed.slice(0, maxTextLen) + TRUNCATION_NOTE);
        }
      }
      break;
    }

    const sliceTarget = str.slice(0, chunkSize);
    const lastNewline = sliceTarget.lastIndexOf('\n');
    let chunk;
    if (lastNewline > chunkSize - 500) {
      chunk = str.slice(0, lastNewline);
      str = str.slice(lastNewline + 1);
    } else {
      chunk = sliceTarget;
      str = str.slice(chunkSize);
    }

    const tentativeBlocks = [...trialBlocks, { type: 'markdown', text: chunk }];
    if (estimatePayloadSize(tentativeBlocks) > maxBytes) {
      const remaining = maxBytes - estimatePayloadSize(trialBlocks);
      const maxTextLen = Math.max(0, remaining - 60);
      if (maxTextLen > 50) {
        chunks.push(chunk.slice(0, maxTextLen) + TRUNCATION_NOTE);
      }
      break;
    }

    chunks.push(chunk);
    trialBlocks.push({ type: 'markdown', text: chunk });
  }

  if (str.length > 0 && chunks.length === maxBlocks) {
    chunks[chunks.length - 1] = chunks[chunks.length - 1].replace(/\n*$/, '') + TRUNCATION_NOTE;
  }

  return chunks;
}

const chunks = splitIntoChunks(text, PER_BLOCK, MAX_BLOCKS, MAX_PAYLOAD_BYTES);
const blocks = chunks.map(t => ({ type: 'markdown', text: t }));
const content = { blocks };

return [{ json: { blocksJson: JSON.stringify(content), output: fullText } }];

const MSG_BUDGET = 8000;

const blocksJson = $('format').first().json.blocksJson;

let blocks;
try {
  blocks = JSON.parse(blocksJson).blocks;
  if (!Array.isArray(blocks) || blocks.length === 0) throw new Error('no blocks');
} catch (e) {
  return [{ json: { blocksJson, part: 1, totalParts: 1 } }];
}

const messages = [];
let current = [];
let currentLen = 0;

for (const block of blocks) {
  const len = (block.text || '').length;
  if (current.length > 0 && currentLen + len > MSG_BUDGET) {
    messages.push(current);
    current = [];
    currentLen = 0;
  }
  current.push(block);
  currentLen += len;
}
if (current.length > 0) messages.push(current);

return messages.map((msgBlocks, i) => ({
  json: {
    blocksJson: JSON.stringify({ blocks: msgBlocks }),
    part: i + 1,
    totalParts: messages.length,
  },
}));

const c = $('Case Loop').first().json;
const raw = $input.first().json;
const out = raw.output || raw;
const okAttempts = (c.ok_attempts || []).map(a => Number(a.attempt));
const agree = new Map();
for (const p of (out.pairs || [])) {
  const a = Number(p.a); const b = Number(p.b);
  if (!isFinite(a) || !isFinite(b) || a === b) continue;
  agree.set(Math.min(a, b) + '-' + Math.max(a, b), p.agree === true);
}
const key = (x, y) => Math.min(x, y) + '-' + Math.max(x, y);
const counts = {};
for (const x of okAttempts) counts[x] = 0;
for (let i = 0; i < okAttempts.length; i++) {
  for (let j = i + 1; j < okAttempts.length; j++) {
    if (agree.get(key(okAttempts[i], okAttempts[j]))) { counts[okAttempts[i]]++; counts[okAttempts[j]]++; }
  }
}
let medoid = okAttempts[0];
for (const x of okAttempts) { if (counts[x] > counts[medoid]) medoid = x; }
const cluster = okAttempts.filter(x => x === medoid || agree.get(key(x, medoid)) === true);

// Accuracy layer: an attempt is accurate when it covers EVERY expected claim
// and contradicts none. Without expected_claims every ok attempt counts.
let expected = c.expected_claims;
if (typeof expected === 'string') { try { expected = JSON.parse(expected); } catch (e) { expected = null; } }
const hasExpected = Array.isArray(expected) && expected.length > 0;
const accSet = new Set();
if (hasExpected && Array.isArray(out.accuracy)) {
  for (const a of out.accuracy) {
    const n = Number(a.attempt);
    if (!okAttempts.includes(n)) continue;
    const missing = Array.isArray(a.missing) ? a.missing.length : 0;
    if (a.contradicted !== true && missing === 0) accSet.add(n);
  }
}
const accurate = hasExpected ? okAttempts.filter(x => accSet.has(x)) : okAttempts;
const clusterAccurate = cluster.filter(x => accurate.includes(x));
const pass = clusterAccurate.length >= Number(c.min_consistent);
return [{ json: {
  run_id: c.run_id, case_id: c.id, case_slug: c.slug,
  status: pass ? 'pass' : 'fail',
  k: c.k, min_consistent: c.min_consistent,
  valid_attempts: okAttempts.length,
  cluster_size: cluster.length,
  accurate_attempts: hasExpected ? accurate.length : null,
  judge: { medoid: medoid, cluster: cluster, accurate: hasExpected ? accurate : null, claims: out.claims || [], pairs: out.pairs || [], accuracy: out.accuracy || null, attempts: c.attempts }
} }];

const c = $input.first().json;
const status = (c.ok_count === 0) ? 'error' : 'fail';
return [{ json: {
  run_id: c.run_id, case_id: c.id, case_slug: c.slug,
  status: status,
  k: c.k, min_consistent: c.min_consistent,
  valid_attempts: c.ok_count,
  cluster_size: null,
  judge: { skipped: true, reason: 'fewer than min_consistent attempts passed anchors', attempts: c.attempts }
} }];
